-- Replace BTP solution industry statistics with the remote baseline data.
-- This table is not referenced by foreign keys, so replacing the table contents is safe for a baseline seed.

delete from public.btp_solution_industry_stat;

--
-- Data for Name: btp_solution_industry_stat; Type: TABLE DATA; Schema: public; Owner: -
--


SELECT pg_catalog.setval(
    'public.btp_solution_industry_stat_stat_id_seq',
    COALESCE((SELECT MAX(stat_id) FROM public.btp_solution_industry_stat), 1),
    (SELECT COUNT(*) > 0 FROM public.btp_solution_industry_stat)
);
